// swift-tools-version:5.9
// The Flutter plugin's iOS side for Swift Package Manager: a bridge to the Kirora iOS SDK
// (kirora-ios), which does the work. CocoaPods builds the same sources through
// ../kirora_flutter.podspec.
import PackageDescription

let package = Package(
    name: "kirora_flutter",
    platforms: [
        .iOS("13.0"),
    ],
    products: [
        .library(name: "kirora-flutter", targets: ["kirora_flutter"]),
    ],
    dependencies: [
        // Generated by Flutter 3.44 and later, beside the plugins.
        .package(name: "FlutterFramework", path: "../FlutterFramework"),
        // KIRORA_IOS_PATH (as the example's Podfile reads it) builds against a kirora-ios checkout.
        Context.environment["KIRORA_IOS_PATH"].map { .package(path: $0) }
            ?? .package(url: "https://github.com/kiroratech/kirora-ios.git", from: "0.1.0"),
    ],
    targets: [
        .target(
            name: "kirora_flutter",
            dependencies: [
                .product(name: "FlutterFramework", package: "FlutterFramework"),
                .product(name: "Kirora", package: "kirora-ios"),
            ]
        ),
    ]
)
